      root: root,
      orb: orb,
      orbLabel: orbLabel,
      panel: panel,
      close: close,
      closeLabel: closeLabel,
      start: start,
      previous: previous.button,
      playPause: playPause.button,
      playPauseLabel: playPause.label,
      playPauseIcon: playPause.iconNode,
      next: next.button,
      stop: stop.button,
      voice: voice,
      voiceLabel: voiceLabel,
      rate: rate,
      speedLabel: speedLabel,
      rateOutput: rateOutput,
      status: status
